var out = {count: 0, bySeverity: {critical: 0, high: 0, medium: 0, low: 0, unknown: 0}, vulns: [], text: '', error: ''};
var rank = {critical: 0, high: 1, medium: 2, low: 3, unknown: 4};

try {
    var inv = JSON.parse(value);
    var pkgs = (inv && inv.packages) || {};
    var names = Object.keys(pkgs);
    if (names.length === 0) {
        return JSON.stringify(out);
    }

    var ignore = {};
    var ignoreRaw = '{$TYPO3_AUDIT_IGNORE}';
    if (ignoreRaw.indexOf('{$') !== 0) {
        var parts = ignoreRaw.split(',');
        for (var n = 0; n < parts.length; n++) {
            var entry = parts[n].replace(/^\s+|\s+$/g, '').toUpperCase();
            if (entry !== '') {
                ignore[entry] = true;
            }
        }
    }

    // Step 1: OSV matches the installed versions against its database.
    var queries = [];
    for (var i = 0; i < names.length; i++) {
        queries.push({'package': {name: names[i], ecosystem: 'Packagist'}, version: pkgs[names[i]]});
    }
    var osvReq = new HttpRequest();
    osvReq.addHeader('Content-Type: application/json');
    var osvBody = osvReq.post('{$TYPO3_AUDIT_OSV_URL}', JSON.stringify({queries: queries}));
    if (osvReq.getStatus() !== 200) {
        throw 'OSV returned HTTP ' + osvReq.getStatus();
    }
    var results = JSON.parse(osvBody).results || [];

    var affected = [];
    var idsByPkg = {};
    for (var r = 0; r < results.length && r < names.length; r++) {
        var vulns = results[r] ? results[r].vulns : null;
        if (vulns && vulns.length) {
            var ids = [];
            for (var w = 0; w < vulns.length; w++) {
                ids.push(vulns[w].id);
            }
            idsByPkg[names[r]] = ids;
            affected.push(names[r]);
        }
    }
    if (affected.length === 0) {
        return JSON.stringify(out);
    }

    // Step 2: Packagist supplies CVE, severity, title and link for the affected packages.
    // Both sides share the GitHub advisory id, so one request is enough to enrich all hits.
    var form = [];
    for (var a = 0; a < affected.length; a++) {
        form.push('packages[]=' + encodeURIComponent(affected[a]));
    }
    var advReq = new HttpRequest();
    advReq.addHeader('Content-Type: application/x-www-form-urlencoded');
    var advBody = advReq.post('{$TYPO3_AUDIT_PACKAGIST_URL}', form.join('&'));
    if (advReq.getStatus() !== 200) {
        throw 'Packagist returned HTTP ' + advReq.getStatus();
    }
    var advisories = JSON.parse(advBody).advisories || {};

    for (var p = 0; p < affected.length; p++) {
        var name = affected[p];
        var byGhsa = {};
        var list = advisories[name] || [];
        for (var l = 0; l < list.length; l++) {
            var sources = list[l].sources || [];
            for (var s = 0; s < sources.length; s++) {
                if (sources[s].name === 'GitHub') {
                    byGhsa[sources[s].remoteId] = list[l];
                }
            }
        }

        var own = idsByPkg[name];
        for (var m = 0; m < own.length; m++) {
            var id = own[m];
            var adv = byGhsa[id];
            var cve = (adv && adv.cve) ? adv.cve : id;
            if (ignore[cve.toUpperCase()] === true || ignore[id.toUpperCase()] === true) {
                continue;
            }
            var sev = (adv && adv.severity) ? String(adv.severity).toLowerCase() : 'unknown';
            if (rank[sev] === undefined) {
                sev = 'unknown';
            }
            out.bySeverity[sev]++;
            out.count++;
            if (out.vulns.length < 100) {
                out.vulns.push({
                    pkg: name,
                    ver: pkgs[name],
                    id: id,
                    cve: cve,
                    sev: sev,
                    title: (adv && adv.title) ? adv.title : '',
                    url: (adv && adv.link) ? adv.link : 'https://osv.dev/vulnerability/' + id
                });
            }
        }
    }

    out.vulns.sort(function (x, y) {
        if (rank[x.sev] !== rank[y.sev]) {
            return rank[x.sev] - rank[y.sev];
        }
        return x.pkg < y.pkg ? -1 : (x.pkg > y.pkg ? 1 : 0);
    });

    var lines = [];
    for (var t = 0; t < out.vulns.length; t++) {
        var v = out.vulns[t];
        lines.push('[' + v.sev + '] ' + v.pkg + ' ' + v.ver + ' - ' + v.cve + ' - ' + v.title + ' ' + v.url);
    }
    out.text = lines.join('\n');
    if (out.text.length > 60000) {
        out.text = out.text.substring(0, 60000) + '\n[truncated]';
    }
} catch (e) {
    // Deliberately emit ONLY the error key: the dependent counter items use
    // "custom on fail -> discard value", so a failed check freezes them at their last
    // known state instead of reporting a false all-clear while the check is broken.
    return JSON.stringify({error: 'composer audit failed: ' + e});
}

return JSON.stringify(out);
